+void MacroAssembler::leal(Register dst, Address src) {
+  if ((src.base() != noreg) && (src.index() == noreg) &&
+      (src.disp() == 0) && (src.reloc() == relocInfo::none)) {
+    // base-only lea, use move (other simple cases not seen).
+    movl(dst, src.base());
+  } else {
+    Assembler::leal(dst, src);
+  }
+}
